async def main():
    from src.scraper.collector import ReviewCollector
    from src.api.autohome_api import close_autohome_api
    c = ReviewCollector()
    total = len(TARGETS)
    done = 0
    failed = []
    for sid, name in TARGETS:
        done += 1
        print(f"===== [{done}/{total}] {name} (sid={sid}) =====", flush=True)
        t0 = time.time()
        try:
            saved = await c.collect(sid, use_llm=True)
            print(f"===== {name} 完成: {saved}条, 用时{time.time()-t0:.0f}s =====", flush=True)
        except Exception as e:
            print(f"===== {name} 失败: {e!r} =====", flush=True)
            failed.append((sid, name, str(e)[:80]))
    await close_autohome_api()
    print(f"\nALL DONE. {total} attempted, {len(failed)} failed", flush=True)
    if failed:
        with open("docs/采集失败名单-2026-09-26.json", "w", encoding="utf-8") as f:
            json.dump(failed, f, ensure_ascii=False, indent=2)
        for sid, name, err in failed:
            print(f"  FAIL {sid} {name}: {err}", flush=True)

asyncio.run(main())
